app = Flask(__name__)

@app.route("/bored", methods=["POST"])
def bored():
    request_json = request.get_json()

    action = request_json["user_request"]["action"]
    user_request = request_json["user_request"]["parameters"]
    response = {"user_request": request_json["user_request"], "action_type": action}

    if action == "chat":
        user_text = user_request["text"]

        bot_text = ""
        for ch in user_text:
            if ch == "<":
                bot_text += "&lt;"
            elif ch == ">":
                bot_text += "&gt;"
            else:
                bot_text += ch

        response["message"] = f"Here is your bot's message: {bot_text}"

    return response

if __name__ == "__main__":
    app.run()

